import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 12345678;
    static class Node {
        int i, j, no;
        Node(int i, int j, int no) {
            this.i = i;
            this.j = j;
            this.no = no;
        }
    }
    static class Capacity {
        int[] no = new int[1000];
        int ind, fl;
    }

    static Capacity[][] caps = new Capacity[100][100];
    static List<Integer>[] v = new ArrayList[1000];
    static int n, t;
    static int[] left = new int[1000], right = new int[1000], col = new int[1000];
    static char[][] grid = new char[1000][1000], grid1 = new char[1000][1000];
    static int[][] d = new int[1000][1000], d1 = new int[1000][1000];
    static Queue<Node> q = new LinkedList<>();

    static void bfs(Node s) {
        for (int i = 0; i <= n; ++i)
            for (int j = 0; j <= n; ++j)
                d[i][j] = INF;
        int i = s.i, j = s.j;
        d[i][j] = 0;
        q.clear();
        q.offer(s);
        while (!q.isEmpty()) {
            Node temp = q.poll();
            i = temp.i; j = temp.j;
            if (grid[i][j] == 'Y') continue;
            if (grid[i][j] == 'Z') continue;
            if (caps[i][j].fl == 1) {
                if (d[i][j] <= t && d[i][j] <= d[i][j]) {
                    for (int l = 1; l <= caps[i][j].ind; ++l) {
                        v[s.no].add(caps[i][j].no[l]);
                    }
                }
            }
            if (d[i][j] >= d[i][j]) continue;
            int[] di = {1, -1, 0, 0};
            int[] dj = {0, 0, 1, -1};
            for (int dir = 0; dir < 4; ++dir) {
                int ni = i + di[dir], nj = j + dj[dir];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                    if (d[ni][nj] > d[i][j] + 1) {
                        d[ni][nj] = d[i][j] + 1;
                        q.offer(new Node(ni, nj, 0));
                    }
                }
            }
        }
    }

    static void bfst(Node s) {
        for (int i = 0; i <= n; ++i)
            for (int j = 0; j <= n; ++j)
                d1[i][j] = INF;
        int i = s.i, j = s.j;
        d1[i][j] = 0;
        Queue<Node> q2 = new LinkedList<>();
        q2.offer(s);
        while (!q2.isEmpty()) {
            Node temp = q2.poll();
            i = temp.i; j = temp.j;
            if (grid[i][j] == 'Y') continue;
            if (grid[i][j] == 'Z') continue;
            if (caps[i][j].fl == 1) {
                if (d1[i][j] <= t && d1[i][j] <= d[i][j]) {
                    for (int l = 1; l <= caps[i][j].ind; ++l) {
                        v[s.no].add(caps[i][j].no[l]);
                    }
                }
            }
            if (d1[i][j] >= d[i][j]) continue;
            int[] di = {1, -1, 0, 0};
            int[] dj = {0, 0, 1, -1};
            for (int dir = 0; dir < 4; ++dir) {
                int ni = i + di[dir], nj = j + dj[dir];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                    if (d1[ni][nj] > d1[i][j] + 1) {
                        d1[ni][nj] = d1[i][j] + 1;
                        q2.offer(new Node(ni, nj, 0));
                    }
                }
            }
        }
    }

    static boolean dfs(int s, int[] left, int[] right, List<Integer>[] v, int size) {
        if (col[s] == 1) return false;
        col[s] = 1;
        for (int i = 0; i < v[s].size(); ++i) {
            int k = v[s].get(i);
            if (left[k] == -1) {
                left[k] = s;
                right[s] = i;
                return true;
            } else if (dfs(left[k], left, right, v, size)) {
                left[k] = s;
                right[s] = i;
                return true;
            }
        }
        return false;
    }

    static int match(int n, List<Integer>[] v, int size) {
        int[] left = new int[size + 1];
        int[] right = new int[size + 1];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        int res = 0;
        boolean done;
        do {
            done = true;
            Arrays.fill(col, 0);
            for (int i = 1; i <= n; ++i) {
